    const diffTime = checkOutDate.getTime() - checkInDate.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }
  formatDate(date) {
    return date.toISOString().split('T')[0];
  }
  isSameDay(date1, date2) {
    return date1.toDateString() === date2.toDateString();
  }
  isCurrentMonth(year, month) {
    const today = new Date();
    return today.getFullYear() === year && today.getMonth() === month;
  }
  isPastMonth(year, month) {
    const today = new Date();
    const monthDate = new Date(year, month);
    return monthDate < new Date(today.getFullYear(), today.getMonth());
  }
  isFutureMonth(year, month) {
    const today = new Date();
    const monthDate = new Date(year, month);
    return monthDate > new Date(today.getFullYear(), today.getMonth());
  }
  generateBookingId() {
    return 'booking_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  }
  generateBookingReference() {
    const today = new Date();
    const dateStr = today.toISOString().slice(0, 10).replace(/-/g, '');
    const randomNum = Math.floor(Math.random() * 999) + 1;
    return `HNA-${dateStr}-${randomNum.toString().padStart(3, '0')}`; // HNA = Hostal Norte Armenia
  }
  populateWhatsAppTemplate(template, booking) {
    return template.replace('{{hostName}}', booking.hostName).replace('{{bookingReference}}', booking.bookingReference).replace('{{propertyTitle}}', booking.propertyTitle).replace('{{guestName}}', `${booking.guestInfo.firstName} ${booking.guestInfo.lastName}`).replace('{{checkInDate}}', this.formatDateForDisplay(booking.checkInDate)).replace('{{checkOutDate}}', this.formatDateForDisplay(booking.checkOutDate)).replace('{{checkInTime}}', '15:00').replace('{{checkOutTime}}', '11:00').replace('{{nights}}', booking.nights.toString()).replace('{{totalGuests}}', booking.guests.total.toString()).replace('{{total}}', booking.priceBreakdown.total.toLocaleString()).replace('{{guestPhone}}', booking.guestInfo.phone).replace('{{guestEmail}}', booking.guestInfo.email).replace('{{specialRequests}}', booking.specialRequests ? `\n🗒️ *Solicitudes especiales:*\n${booking.specialRequests}` : '');
  }
  generateWhatsAppUrl(phone, message) {
    const cleanPhone = phone.replace(/\D/g, '');
    const encodedMessage = encodeURIComponent(message);
    return `https://wa.me/${cleanPhone}?text=${encodedMessage}`;
  }
  formatDateForDisplay(date) {
    const dateObj = new Date(date);
    return dateObj.toLocaleDateString('es-CO', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  }
  initializeProgress() {
    const progress = {
      currentStep: 1,
      totalSteps: 4,
      steps: [{
        stepNumber: 1,
        stepName: 'dates',
        isCompleted: false,
        isValid: false,
        errors: []
      }, {
        stepNumber: 2,
        stepName: 'guests',
        isCompleted: false,
        isValid: false,
        errors: []
      }, {
        stepNumber: 3,
        stepName: 'details',
        isCompleted: false,
        isValid: false,
        errors: []
      }, {
        stepNumber: 4,
        stepName: 'review',
        isCompleted: false,
        isValid: false,
        errors: []
      }],
      canProceed: false,
      completionPercentage: 0
    };
    this.bookingProgressSubject.next(progress);
  }
  updateProgress() {
    const current = this.currentBookingSubject.value;
    const progress = this.bookingProgressSubject.value;
    if (!current || !progress) return;
    // Actualizar validación de cada paso
    progress.steps[0].isValid = !!(current.checkInDate && current.checkOutDate);
    progress.steps[1].isValid = !!(current.guests && current.guests.total > 0);
    progress.steps[2].isValid = !!(current.guestInfo?.firstName && current.guestInfo?.email);
    // Calcular progreso
    const completedSteps = progress.steps.filter(s => s.isValid).length;
    progress.completionPercentage = completedSteps / progress.totalSteps * 100;
    progress.canProceed = progress.steps[progress.currentStep - 1]?.isValid || false;
    this.bookingProgressSubject.next(progress);
  }
  addBooking(booking) {
    const current = this.bookingsSubject.value;
    this.bookingsSubject.next([...current, booking]);
    this.saveBookingsToStorage([...current, booking]);
  }
  loadBookingsFromStorage() {
    try {
      const saved = localStorage.getItem('hostal_norte_bookings');
      if (saved) {
        const bookings = JSON.parse(saved);
        this.bookingsSubject.next(bookings);
      }
    } catch (error) {
      console.warn('Error loading bookings from storage:', error);
    }
  }
  saveBookingsToStorage(bookings) {
    try {
      localStorage.setItem('hostal_norte_bookings', JSON.stringify(bookings));
    } catch (error) {
      console.warn('Error saving bookings to storage:', error);
    }
  }
  // Los demás métodos permanecen igual...
  validateCurrentBooking() {
    const current = this.currentBookingSubject.value;
    if (!current || !current.checkInDate || !current.checkOutDate || !current.propertyId) {
      return of({
        isValid: false,
        errors: [{
          code: 'INCOMPLETE_BOOKING',
          message: 'Información de reserva incompleta',
          field: 'range'
        }],
        warnings: []
      });
    }
    return this.validateDateSelection(current.propertyId, current.checkInDate, current.checkOutDate);
  }
  sendWhatsAppMessage(booking) {
    const template = BOOKING_CONSTANTS.WHATSAPP_TEMPLATES['new-booking'];
    const messageText = this.populateWhatsAppTemplate(template, booking);
    const whatsappUrl = this.generateWhatsAppUrl(booking.hostWhatsapp, messageText);
    const message = {
      bookingId: booking.id,
      hostWhatsapp: booking.hostWhatsapp,
      messageText,
      messageType: 'new-booking',
      isSent: false,
      whatsappUrl
    };
    setTimeout(() => {
      message.isSent = true;
      message.sentAt = new Date().toISOString();
      this.updateBookingWhatsAppStatus(booking.id, true);
    }, 1000);
    return of(message).pipe(delay(100));
  }
  updateBookingWhatsAppStatus(bookingId, sent) {
    const current = this.bookingsSubject.value;
    const updated = current.map(booking => booking.id === bookingId ? {
      ...booking,
      whatsappMessageSent: sent,
      updatedAt: new Date().toISOString()
    } : booking);
    this.bookingsSubject.next(updated);
    this.saveBookingsToStorage(updated);
  }
  clearCurrentBooking() {
    this.currentBookingSubject.next(null);
    this.bookingProgressSubject.next(null);
  }
  getBookings() {
    return this.bookings$;
  }
  getBookingById(id) {
    return this.bookings$.pipe(map(bookings => bookings.find(b => b.id === id)));
  }
