// 📁 src/app/core/services/room-search.service.ts

import { Injectable } from '@angular/core';
import { Observable, BehaviorSubject, combineLatest } from 'rxjs';
import { map, debounceTime, distinctUntilChanged } from 'rxjs/operators';

import { Room, RoomType, RoomAmenityType } from '../models/room.interface';
import { 
  RoomSearchParams, 
  RoomFilters, 
  FilterState, 
  RoomSearchConfig,
  RoomSuggestion,
  RoomSearchStats,
  DEFAULT_ROOM_FILTERS,
  DEFAULT_ROOM_SEARCH_CONFIG,
  DEFAULT_ROOM_SEARCH_PARAMS,
  ROOM_SUGGESTIONS,
  getActiveFilters
} from '../models/room-search.interface';

import { RoomService } from './room.service';

@Injectable({
  providedIn: 'root'
})
export class RoomSearchService {

  // 📱 REACTIVE STATE
  private searchParamsSubject = new BehaviorSubject<RoomSearchParams>(DEFAULT_ROOM_SEARCH_PARAMS);
  private filtersSubject = new BehaviorSubject<RoomFilters>(DEFAULT_ROOM_FILTERS);
  private configSubject = new BehaviorSubject<RoomSearchConfig>(DEFAULT_ROOM_SEARCH_CONFIG);

  // 🔍 PUBLIC OBSERVABLES
  public searchParams$ = this.searchParamsSubject.asObservable();
  public filters$ = this.filtersSubject.asObservable();
  public config$ = this.configSubject.asObservable();

  constructor(private roomService: RoomService) {}

  // ================================
  // 🔍 BÚSQUEDA PRINCIPAL
  // ================================

  searchRooms(params: RoomSearchParams): Observable<Room[]> {
    this.updateSearchParams(params);
    
    return this.roomService.getRooms().pipe(
      map(rooms => this.filterBySearchParams(rooms, params))
    );
  }

  searchWithFilters(params: RoomSearchParams, filters: RoomFilters): Observable<Room[]> {
    return this.roomService.searchWithFilters({
      roomTypes: this.getActiveRoomTypes(filters),
      capacity: params.guests,
      priceRange: {
        min: filters.minPrice,
        max: filters.maxPrice
      },
      amenities: this.getActiveAmenities(filters),
      minRating: filters.minRating,
      availableDates: params.checkIn && params.checkOut ? {
        checkIn: params.checkIn,
        checkOut: params.checkOut
      } : undefined
    });
  }

  getFilteredResults(): Observable<Room[]> {
    return combineLatest([
      this.roomService.getRooms(),
      this.searchParams$,
      this.filters$,
      this.config$
    ]).pipe(
      debounceTime(300),
      distinctUntilChanged(),
      map(([rooms, searchParams, filters, config]) => {
        let filtered = this.filterBySearchParams(rooms, searchParams);

        filtered = this.applyRoomFilters(filtered, filters);
        filtered = this.roomService.sortRooms(filtered, config.sortBy);
        
        return filtered;
      })
    );
  }

  searchByText(searchTerm: string): Observable<Room[]> {
    return this.roomService.searchByText(searchTerm);
  }

  // ================================
  // 🎛️ FILTROS ESPECÍFICOS PARA HABITACIONES
  // ================================

  private applyRoomFilters(rooms: Room[], filters: RoomFilters): Room[] {
    return rooms.filter(room => {
      // Filtrar por tipos de habitación
      const roomTypeMatch = !this.hasActiveRoomTypeFilters(filters) || 
        filters.roomTypes[room.roomType];

      // Filtrar por amenidades
      const amenityMatch = !this.hasActiveAmenityFilters(filters) || 
        this.checkAmenitiesMatch(room.amenities, filters.amenities);

      // Filtrar por características especiales
      const featureMatch = this.checkFeaturesMatch(room, filters.features);

      // Filtrar por capacidad
      const capacityMatch = this.checkCapacityMatch(room.maxGuests, filters.capacity);

      // Filtrar por rango de precios
      const priceMatch = room.pricing.basePrice >= filters.minPrice && 
                        room.pricing.basePrice <= filters.maxPrice;

      // Filtrar por calificación
      const ratingMatch = room.stats.rating >= filters.minRating;

      // Filtrar por huéspedes máximos
      const guestMatch = room.maxGuests >= filters.maxGuests;

      // Solo habitaciones disponibles (si está activado)
      const availabilityMatch = !filters.availableOnly || 
        (room.availability.isActive && room.availability.isAvailable);

      return roomTypeMatch && amenityMatch && featureMatch && capacityMatch && 
             priceMatch && ratingMatch && guestMatch && availabilityMatch;
    });
  }

  private checkAmenitiesMatch(roomAmenities: RoomAmenityType[], filterAmenities: any): boolean {
    const activeAmenities = Object.entries(filterAmenities)
      .filter(([_, active]) => active)
      .map(([amenity, _]) => amenity as RoomAmenityType);

    return activeAmenities.length === 0 || 
           activeAmenities.every(amenity => roomAmenities.includes(amenity));
  }

  private checkFeaturesMatch(room: Room, features: any): boolean {
    const checks = {
      hasWorkspace: () => room.amenities.includes('escritorio') && room.amenities.includes('silla-trabajo'),
      hasBalcony: () => room.amenities.includes('balcon'),
      hasPrivateBathroom: () => room.bathroomType === 'privado',
      hasAirConditioning: () => room.amenities.includes('aire-acondicionado'),
      hasSmartTV: () => room.amenities.includes('tv-smart'),
      hasSafe: () => room.amenities.includes('caja-fuerte')
    };

    return Object.entries(features).every(([feature, active]) => {
      if (!active) return true;
      const checkFn = checks[feature as keyof typeof checks];
      return checkFn ? checkFn() : true;
    });
  }

  private checkCapacityMatch(roomCapacity: number, capacityFilters: any): boolean {
    const activeCapacities = Object.entries(capacityFilters)
      .filter(([_, active]) => active)
      .map(([capacity, _]) => capacity);

    if (activeCapacities.length === 0) return true;

    return activeCapacities.some(capacity => {
      switch (capacity) {
        case 'guests1': return roomCapacity >= 1;
        case 'guests2': return roomCapacity >= 2;
        case 'guests3': return roomCapacity >= 3;
        case 'guests4Plus': return roomCapacity >= 4;
        default: return true;
      }
    });
  }

  // ================================
  // 🎛️ GESTIÓN DE ESTADO
  // ================================

  updateSearchParams(params: Partial<RoomSearchParams>): void {
    const current = this.searchParamsSubject.value;
    this.searchParamsSubject.next({ ...current, ...params });
  }

  updateFilters(filters: Partial<RoomFilters>): void {
    const current = this.filtersSubject.value;
    this.filtersSubject.next({ ...current, ...filters });
  }

  updateRoomTypeFilter(type: RoomType, active: boolean): void {
    const current = this.filtersSubject.value;
    this.filtersSubject.next({
      ...current,
      roomTypes: {
        ...current.roomTypes,
        [type]: active
      }
    });
  }

  updateAmenityFilter(amenity: RoomAmenityType, active: boolean): void {
    const current = this.filtersSubject.value;
    this.filtersSubject.next({
      ...current,
      amenities: {
        ...current.amenities,
        [amenity]: active
      }
    });
  }

  updatePriceRange(min: number, max: number): void {
    const current = this.filtersSubject.value;
    this.filtersSubject.next({
      ...current,
      minPrice: min,
      maxPrice: max
    });
  }

  updateCapacityFilter(guests: number): void {
    const current = this.filtersSubject.value;
    this.filtersSubject.next({
      ...current,
      maxGuests: guests
    });
  }

  clearFilters(): void {
    this.filtersSubject.next(DEFAULT_ROOM_FILTERS);
  }

  applyQuickFilter(filterType: 'business' | 'family' | 'romantic' | 'budget'): void {
    let quickFilters: Partial<RoomFilters>;
    
    switch (filterType) {
      case 'business':
        quickFilters = {
          roomTypes: { ...DEFAULT_ROOM_FILTERS.roomTypes, doble: true },
          amenities: { 
            ...DEFAULT_ROOM_FILTERS.amenities, 
            'escritorio': true,
            'aire-acondicionado': true,
            'tv-smart': true 
          },
          features: { 
            ...DEFAULT_ROOM_FILTERS.features, 
            hasWorkspace: true 
          }
        };
        break;
        
      case 'family':
        quickFilters = {
          roomTypes: { 
            ...DEFAULT_ROOM_FILTERS.roomTypes, 
            familiar: true, 
            triple: true 
          },
          capacity: { 
            ...DEFAULT_ROOM_FILTERS.capacity, 
            guests4Plus: true 
          }
        };
        break;
        
      case 'romantic':
        quickFilters = {
          roomTypes: { 
            ...DEFAULT_ROOM_FILTERS.roomTypes, 
            suite: true 
          },
          amenities: { 
            ...DEFAULT_ROOM_FILTERS.amenities, 
            'balcon': true,
            'minibar': true 
          },
          features: { 
            ...DEFAULT_ROOM_FILTERS.features, 
            hasBalcony: true 
          }
        };
        break;
        
      case 'budget':
        quickFilters = {
          priceRange: { 
            ...DEFAULT_ROOM_FILTERS.priceRange, 
            budget: true 
          },
          maxPrice: 60000
        };
        break;
        
      default:
        quickFilters = {};
    }
    
    this.updateFilters(quickFilters);
  }

  updateConfig(config: Partial<RoomSearchConfig>): void {
    const current = this.configSubject.value;
    this.configSubject.next({ ...current, ...config });
  }

  setViewMode(mode: 'grid' | 'list'): void {
    this.updateConfig({ viewMode: mode });
  }

  setSortBy(sortBy: string): void {
    this.updateConfig({ sortBy });
  }

  setCurrentPage(page: number): void {
    this.updateConfig({ currentPage: page });
  }

  // ================================
  // 📊 INFORMACIÓN Y ESTADÍSTICAS
  // ================================

  getFilterState(): Observable<FilterState> {
    return this.filters$.pipe(
      map(filters => ({
        activeFilters: filters,
        hasActiveFilters: this.hasAnyActiveFilters(filters),
        filterCount: this.countActiveFilters(filters)
      }))
    );
  }

  getRoomSuggestions(): RoomSuggestion[] {
    return ROOM_SUGGESTIONS;
  }

  getSearchStats(): Observable<RoomSearchStats> {
    return this.getFilteredResults().pipe(
      map(rooms => ({
        totalResults: rooms.length,
        availableRooms: rooms.filter(r => r.availability.isAvailable).length,
        averagePrice: rooms.length > 0 
          ? Math.round(rooms.reduce((sum, r) => sum + r.pricing.basePrice, 0) / rooms.length)
          : 0,
        priceRange: {
          min: rooms.length > 0 ? Math.min(...rooms.map(r => r.pricing.basePrice)) : 0,
          max: rooms.length > 0 ? Math.max(...rooms.map(r => r.pricing.basePrice)) : 0
        },
        mostPopularType: this.getMostPopularRoomType(rooms),
        averageRating: rooms.length > 0 
          ? Math.round((rooms.reduce((sum, r) => sum + r.stats.rating, 0) / rooms.length) * 10) / 10
          : 0
      }))
    );
  }

  // ================================
  //  VALIDACIÓN Y UTILIDADES
  // ================================

  validateSearchDates(checkIn: string, checkOut: string): { valid: boolean; error?: string } {
    if (!checkIn || !checkOut) {
      return { valid: false, error: 'Fechas de llegada y salida son requeridas' };
    }

    const checkInDate = new Date(checkIn);
    const checkOutDate = new Date(checkOut);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (checkInDate < today) {
      return { valid: false, error: 'La fecha de llegada no puede ser en el pasado' };
    }

    if (checkOutDate <= checkInDate) {
      return { valid: false, error: 'La fecha de salida debe ser posterior a la llegada' };
    }

    const nights = this.calculateNights(checkIn, checkOut);
    if (nights > 90) {
      return { valid: false, error: 'La estancia no puede ser mayor a 90 días' };
    }

    return { valid: true };
  }

  calculateNights(checkIn: string, checkOut: string): number {
    if (!checkIn || !checkOut) return 0;
    
    const checkInDate = new Date(checkIn);
    const checkOutDate = new Date(checkOut);
    const timeDiff = checkOutDate.getTime() - checkInDate.getTime();
    return Math.ceil(timeDiff / (1000 * 3600 * 24));
  }

  getRecommendations(params?: RoomSearchParams): Observable<Room[]> {
    if (params?.guests) {
      return this.roomService.getRoomsByCapacity(params.guests);
    } else {
      return this.roomService.getFeaturedRooms();
    }
  }

  // ================================
  // 🔧 MÉTODOS PRIVADOS
  // ================================

  private filterBySearchParams(rooms: Room[], params: RoomSearchParams): Room[] {
    let filtered = [...rooms];

    // Filtrar por capacidad de huéspedes
    if (params.guests > 0) {
      filtered = filtered.filter(room => room.maxGuests >= params.guests);
    }

    // Filtrar por tipo de habitación específico
    if (params.roomType) {
      filtered = filtered.filter(room => room.roomType === params.roomType);
    }

    // Solo habitaciones activas y disponibles
    filtered = filtered.filter(room => 
      room.availability.isActive && room.availability.isAvailable
    );

    return filtered;
  }

  private getActiveRoomTypes(filters: RoomFilters): RoomType[] {
    return Object.entries(filters.roomTypes)
      .filter(([_, active]) => active)
      .map(([type, _]) => type as RoomType);
  }

  private getActiveAmenities(filters: RoomFilters): RoomAmenityType[] {
    return Object.entries(filters.amenities)
      .filter(([_, active]) => active)
      .map(([amenity, _]) => amenity as RoomAmenityType);
  }

  private hasActiveRoomTypeFilters(filters: RoomFilters): boolean {
    return Object.values(filters.roomTypes).some(filter => filter);
  }

  private hasActiveAmenityFilters(filters: RoomFilters): boolean {
    return Object.values(filters.amenities).some(filter => filter);
  }

  private hasAnyActiveFilters(filters: RoomFilters): boolean {
    return this.hasActiveRoomTypeFilters(filters) ||
           this.hasActiveAmenityFilters(filters) ||
           Object.values(filters.features).some(filter => filter) ||
           Object.values(filters.capacity).some(filter => filter) ||
           Object.values(filters.priceRange).some(filter => filter) ||
           filters.minRating > 0 ||
           filters.minPrice > 0 ||
           filters.maxPrice < 200000;
  }

  private countActiveFilters(filters: RoomFilters): number {
    let count = 0;
    
    count += Object.values(filters.roomTypes).filter(active => active).length;
    count += Object.values(filters.amenities).filter(active => active).length;
    count += Object.values(filters.features).filter(active => active).length;
    count += Object.values(filters.capacity).filter(active => active).length;
    count += Object.values(filters.priceRange).filter(active => active).length;
    
    if (filters.minRating > 0) count++;
    if (filters.minPrice > 0 || filters.maxPrice < 200000) count++;
    
    return count;
  }

  private getMostPopularRoomType(rooms: Room[]): RoomType {
    if (rooms.length === 0) return 'doble';
    
    const typeCount = rooms.reduce((acc, room) => {
      acc[room.roomType] = (acc[room.roomType] || 0) + 1;
      return acc;
    }, {} as Record<RoomType, number>);
    
    return Object.entries(typeCount)
      .sort(([,a], [,b]) => b - a)[0]?.[0] as RoomType || 'doble';
  }
}

// ================================
// 📁 src/app/core/services/room-booking.service.ts
// ================================

import { Injectable } from '@angular/core';
import { Observable, BehaviorSubject, of, throwError, combineLatest } from 'rxjs';
import { map, delay, switchMap, tap } from 'rxjs/operators';

import { RoomService } from './room.service';
import { EstablishmentService } from './establishment.service';
import { Room } from '../models/room.interface';
import { 
  Booking, BookingRequest, BookingStatus, PriceBreakdown, PriceCalculatorConfig,
  BookingValidationRules, BookingProgress, WhatsAppMessage, BookingStats,
  BOOKING_CONSTANTS, PartialBookingRequest, BookingUpdate, BookingSearchParams
} from '../models/booking.interface';
import { 
  DayAvailability, DateSelection, CalendarConfig, DateString,
  CALENDAR_CONSTANTS, CalendarMonth, DateValidationResult
} from '../models/calendar.interface';

@Injectable({
  providedIn: 'root'
})
export class RoomBookingService {
  
  // ================================
  // 🗂️ ESTADO Y OBSERVABLES
  // ================================
  
  private bookingsSubject = new BehaviorSubject<Booking[]>([]);
  private currentBookingSubject = new BehaviorSubject<PartialBookingRequest | null>(null);
  private bookingProgressSubject = new BehaviorSubject<BookingProgress | null>(null);
  
  public bookings$ = this.bookingsSubject.asObservable();
  public currentBooking$ = this.currentBookingSubject.asObservable();
  public bookingProgress$ = this.bookingProgressSubject.asObservable();
  
  private priceConfig: PriceCalculatorConfig = BOOKING_CONSTANTS.DEFAULT_PRICE_CONFIG;
  private validationRules: BookingValidationRules = BOOKING_CONSTANTS.DEFAULT_VALIDATION_RULES;
  private calendarConfig: CalendarConfig = CALENDAR_CONSTANTS.DEFAULT_CONFIG;

  constructor(
    private roomService: RoomService,
    private establishmentService: EstablishmentService
  ) {
    this.loadBookingsFromStorage();
  }

  // ================================
  // 📅 DISPONIBILIDAD Y CALENDARIO
  // ================================

  getRoomAvailability(roomId: string, startDate: DateString, endDate: DateString): Observable<DayAvailability[]> {
    return this.roomService.getRoomById(roomId).pipe(
      map(room => {
        if (!room) return [];
        
        const availability: DayAvailability[] = [];
        const start = new Date(startDate);
        const end = new Date(endDate);
        
        for (let date = new Date(start); date <= end; date.setDate(date.getDate() + 1)) {
          const dateString = this.formatDate(date);
          const dayAvailability = this.generateDayAvailability(room, dateString);
          availability.push(dayAvailability);
        }
        
        return availability;
      }),
      delay(200)
    );
  }

  getCalendarMonth(roomId: string, year: number, month: number): Observable<CalendarMonth> {
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startDate = this.formatDate(firstDay);
    const endDate = this.formatDate(lastDay);
    
    return this.getRoomAvailability(roomId, startDate, endDate).pipe(
      map(days => ({
        year,
        month: month as any,
        monthName: CALENDAR_CONSTANTS.MONTH_NAMES[month],
        monthNameShort: CALENDAR_CONSTANTS.MONTH_NAMES_SHORT[month],
        days,
        totalDays: days.length,
        previousMonthDays: [],
        nextMonthDays: [],
        availableDays: days.filter(d => d.isAvailable).length,
        bookedDays: days.filter(d => d.isBooked).length,
        blockedDays: days.filter(d => d.isBlocked).length,
        isCurrentMonth: this.isCurrentMonth(year, month),
        isPastMonth: this.isPastMonth(year, month),
        isFutureMonth: this.isFutureMonth(year, month)
      }))
    );
  }

  validateDateSelection(roomId: string, checkIn: DateString, checkOut: DateString): Observable<DateValidationResult> {
    const errors: DateValidationResult['errors'] = [];
    const warnings: DateValidationResult['warnings'] = [];
    const checkInDate = new Date(checkIn);
    const checkOutDate = new Date(checkOut);
    const today = new Date();
    const nights = this.calculateNights(checkIn, checkOut);

    // Validaciones básicas (mismas que antes)
    if (checkInDate < today) {
      errors.push({
        code: 'PAST_DATE',
        message: 'La fecha de llegada no puede ser en el pasado',
        field: 'checkIn'
      });
    }

    if (checkOutDate <= checkInDate) {
      errors.push({
        code: 'INVALID_RANGE',
        message: 'La fecha de salida debe ser posterior a la fecha de llegada',
        field: 'checkOut'
      });
    }

    // Validaciones específicas de la habitación
    return this.roomService.getRoomById(roomId).pipe(
      map(room => {
        if (room && room.availability.minimumStay && nights < room.availability.minimumStay) {
          errors.push({
            code: 'MIN_STAY',
            message: `Esta habitación requiere una estancia mínima de ${room.availability.minimumStay} noches`,
            field: 'range'
          });
        }
        
        if (nights >= 7 && room?.pricing.weeklyDiscount) {
          warnings.push({
            code: 'WEEKLY_DISCOUNT',
            message: `Descuento semanal del ${room.pricing.weeklyDiscount}% aplicado automáticamente`
          });
        }
        
        if (nights >= 28 && room?.pricing.monthlyDiscount) {
          warnings.push({
            code: 'MONTHLY_DISCOUNT',
            message: `Descuento mensual del ${room.pricing.monthlyDiscount}% aplicado automáticamente`
          });
        }
        
        return {
          isValid: errors.length === 0,
          errors,
          warnings
        };
      }),
      delay(100)
    );
  }

  // ================================
  // 💰 CÁLCULO DE PRECIOS
  // ================================

  calculatePrice(roomId: string, checkIn: DateString, checkOut: DateString): Observable<PriceBreakdown> {
    return this.roomService.getRoomById(roomId).pipe(
      map(room => {
        if (!room) {
          throw new Error('Habitación no encontrada');
        }
        
        const nights = this.calculateNights(checkIn, checkOut);
        const pricePerNight = room.pricing.basePrice;
        let subtotal = pricePerNight * nights;
        
        const breakdown: PriceBreakdown = {
          pricePerNight,
          nights,
          subtotal,
          iva: { percentage: 0, amount: 0 },
          total: 0,
          totalCOP: 0
        };

        // Aplicar descuentos de la habitación
        if (this.priceConfig.applyWeeklyDiscount && nights >= 7 && room.pricing.weeklyDiscount) {
          const discountAmount = Math.round(subtotal * (room.pricing.weeklyDiscount / 100));
          breakdown.weeklyDiscount = {
            percentage: room.pricing.weeklyDiscount,
            amount: discountAmount
          };
          subtotal -= discountAmount;
          breakdown.subtotal = subtotal;
        }

        if (this.priceConfig.applyMonthlyDiscount && nights >= 28 && room.pricing.monthlyDiscount) {
          const originalSubtotal = pricePerNight * nights;
          const discountAmount = Math.round(originalSubtotal * (room.pricing.monthlyDiscount / 100));
          breakdown.monthlyDiscount = {
            percentage: room.pricing.monthlyDiscount,
            amount: discountAmount
          };
          subtotal = originalSubtotal - discountAmount;
          breakdown.subtotal = subtotal;
        }

        // Aplicar tarifas del establecimiento
        if (this.priceConfig.cleaningFeePercentage > 0) {
          breakdown.cleaningFee = Math.round(subtotal * (this.priceConfig.cleaningFeePercentage / 100));
        }

        if (this.priceConfig.serviceFeePercentage > 0) {
          breakdown.serviceFee = Math.round(subtotal * (this.priceConfig.serviceFeePercentage / 100));
        }

        const totalBeforeTax = subtotal + (breakdown.cleaningFee || 0) + (breakdown.serviceFee || 0);

        breakdown.iva = {
          percentage: this.priceConfig.ivaPercentage,
          amount: Math.round(totalBeforeTax * (this.priceConfig.ivaPercentage / 100))
        };

        breakdown.total = totalBeforeTax + breakdown.iva.amount;
        breakdown.totalCOP = breakdown.total;
        
        return breakdown;
      }),
      delay(100)
    );
  }

  // ================================
  // 📋 GESTIÓN DE RESERVAS
  // ================================

  initializeBooking(roomId: string): Observable<PartialBookingRequest> {
    return combineLatest([
      this.roomService.getRoomById(roomId),
      this.establishmentService.getEstablishmentInfo()
    ]).pipe(
      map(([room, establishment]) => {
        if (!room) {
          throw new Error('Habitación no encontrada');
        }
        
        const initialBooking: PartialBookingRequest = {
          propertyId: roomId, // Mantenemos la compatibilidad usando propertyId como roomId
          guests: {
            adults: 1,
            children: 0,
            infants: 0,
            total: 1
          },
          purposeOfStay: 'vacation',
          isFirstTimeInArmenia: true,
          hostWhatsapp: establishment.contactInfo.whatsapp,
          hostName: establishment.host.name
        };
        
        this.currentBookingSubject.next(initialBooking);
        this.initializeProgress();
        
        return initialBooking;
      })
    );
  }

  // El resto de métodos del booking service permanecen igual,
  // solo cambiando las referencias de "property" por "room" donde sea necesario

  updateCurrentBooking(updates: Partial<PartialBookingRequest>): Observable<PartialBookingRequest> {
    const current = this.currentBookingSubject.value;
    if (!current) {
      return throwError('No hay una reserva activa');
    }
    
    const updated = { ...current, ...updates };
    this.currentBookingSubject.next(updated);
    this.updateProgress();
    
    return of(updated);
  }

  submitBooking(): Observable<Booking> {
    const currentBooking = this.currentBookingSubject.value;
    if (!currentBooking) {
      return throwError('No hay una reserva para enviar');
    }
    
    return this.validateCurrentBooking().pipe(
      switchMap(validation => {
        if (!validation.isValid) {
          return throwError('La reserva contiene errores: ' + validation.errors.map((e: any) => e.message).join(', '));
        }
        
        return this.createBooking(currentBooking as BookingRequest);
      })
    );
  }

  private createBooking(bookingRequest: BookingRequest): Observable<Booking> {
    return combineLatest([
      this.roomService.getRoomById(bookingRequest.propertyId), // propertyId = roomId
      this.establishmentService.getEstablishmentInfo(),
      this.calculatePrice(bookingRequest.propertyId, bookingRequest.checkInDate, bookingRequest.checkOutDate)
    ]).pipe(
      map(([room, establishment, priceBreakdown]) => {
        if (!room) {
          throw new Error('Habitación no encontrada');
        }
        
        const booking: Booking = {
          id: this.generateBookingId(),
          bookingReference: this.generateBookingReference(),
          status: 'pending',
          paymentStatus: 'pending',
          
          propertyId: room.id,
          propertyTitle: `${room.name} - ${establishment.name}`,
          propertyImage: room.images.main,
          propertyAddress: establishment.address,
          propertyZone: establishment.areaInfo.neighborhood,
          
          checkInDate: bookingRequest.checkInDate,
          checkOutDate: bookingRequest.checkOutDate,
          nights: this.calculateNights(bookingRequest.checkInDate, bookingRequest.checkOutDate),
          
          guests: bookingRequest.guests,
          guestInfo: bookingRequest.guestInfo,
          
          priceBreakdown,
          
          hostName: establishment.host.name,
          hostWhatsapp: establishment.contactInfo.whatsapp,
          
          whatsappMessageSent: false,
          
          specialRequests: bookingRequest.specialRequests,
          estimatedArrivalTime: bookingRequest.estimatedArrivalTime,
          purposeOfStay: bookingRequest.purposeOfStay,
          
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          
          cancellationPolicy: establishment.policies.cancellationPolicy,
          minimumStay: room.availability.minimumStay || 1
        };
        
        // Guardar la reserva
        this.addBooking(booking);
        
        // Enviar mensaje de WhatsApp
        this.sendWhatsAppMessage(booking).subscribe();
        
        return booking;
      }),
      delay(500)
    );
  }

  // ================================
  // 🔧 MÉTODOS PRIVADOS (iguales que antes)
  // ================================

  private generateDayAvailability(room: Room, date: DateString): DayAvailability {
    const dateObj = new Date(date);
    const today = new Date();
    const dayOfWeek = dateObj.getDay() as any;
    
    // Mock: algunas fechas bloqueadas aleatoriamente
    const isBlocked = Math.random() < 0.1; // 10% de días bloqueados
    const isBooked = Math.random() < 0.15;  // 15% de días con reserva
    
    return {
      date,
      dayOfWeek,
      dayNumber: dateObj.getDate(),
      isAvailable: !isBlocked && !isBooked && dateObj >= today,
      isBlocked,
      isBooked,
      isPastDate: dateObj < today,
      isToday: this.isSameDay(dateObj, today),
      minimumStay: room.availability.minimumStay,
      hasSpecialPrice: false,
      checkInAllowed: true,
      checkOutAllowed: true
    };
  }

  private calculateNights(checkIn: DateString, checkOut: DateString): number {
    const checkInDate = new Date(checkIn);
    const checkOutDate = new Date(checkOut);
    const diffTime = checkOutDate.getTime() - checkInDate.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  }

  private formatDate(date: Date): DateString {
    return date.toISOString().split('T')[0];
  }

  private isSameDay(date1: Date, date2: Date): boolean {
    return date1.toDateString() === date2.toDateString();
  }

  private isCurrentMonth(year: number, month: number): boolean {
    const today = new Date();
    return today.getFullYear() === year && today.getMonth() === month;
  }

  private isPastMonth(year: number, month: number): boolean {
    const today = new Date();
    const monthDate = new Date(year, month);
    return monthDate < new Date(today.getFullYear(), today.getMonth());
  }

  private isFutureMonth(year: number, month: number): boolean {
    const today = new Date();
    const monthDate = new Date(year, month);
    return monthDate > new Date(today.getFullYear(), today.getMonth());
  }

  private generateBookingId(): string {
    return 'booking_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  }

  private generateBookingReference(): string {
    const today = new Date();
    const dateStr = today.toISOString().slice(0, 10).replace(/-/g, '');
    const randomNum = Math.floor(Math.random() * 999) + 1;
    return `HNA-${dateStr}-${randomNum.toString().padStart(3, '0')}`; // HNA = Hostal Norte Armenia
  }

  private populateWhatsAppTemplate(template: string, booking: Booking): string {
    return template
      .replace('{{hostName}}', booking.hostName)
      .replace('{{bookingReference}}', booking.bookingReference)
      .replace('{{propertyTitle}}', booking.propertyTitle)
      .replace('{{guestName}}', `${booking.guestInfo.firstName} ${booking.guestInfo.lastName}`)
      .replace('{{checkInDate}}', this.formatDateForDisplay(booking.checkInDate))
      .replace('{{checkOutDate}}', this.formatDateForDisplay(booking.checkOutDate))
      .replace('{{checkInTime}}', '15:00')
      .replace('{{checkOutTime}}', '11:00')
      .replace('{{nights}}', booking.nights.toString())
      .replace('{{totalGuests}}', booking.guests.total.toString())
      .replace('{{total}}', booking.priceBreakdown.total.toLocaleString())
      .replace('{{guestPhone}}', booking.guestInfo.phone)
      .replace('{{guestEmail}}', booking.guestInfo.email)
      .replace('{{specialRequests}}', booking.specialRequests ? 
        `\n🗒️ *Solicitudes especiales:*\n${booking.specialRequests}` : '');
  }

  private generateWhatsAppUrl(phone: string, message: string): string {
    const cleanPhone = phone.replace(/\D/g, '');
    const encodedMessage = encodeURIComponent(message);
    return `https://wa.me/${cleanPhone}?text=${encodedMessage}`;
  }

  private formatDateForDisplay(date: DateString): string {
    const dateObj = new Date(date);
    return dateObj.toLocaleDateString('es-CO', {
      weekday: 'long',
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  }

  private initializeProgress(): void {
    const progress: BookingProgress = {
      currentStep: 1,
      totalSteps: 4,
      steps: [
        { stepNumber: 1, stepName: 'dates', isCompleted: false, isValid: false, errors: [] },
        { stepNumber: 2, stepName: 'guests', isCompleted: false, isValid: false, errors: [] },
        { stepNumber: 3, stepName: 'details', isCompleted: false, isValid: false, errors: [] },
        { stepNumber: 4, stepName: 'review', isCompleted: false, isValid: false, errors: [] }
      ],
      canProceed: false,
      completionPercentage: 0
    };
    
    this.bookingProgressSubject.next(progress);
  }

  private updateProgress(): void {
    const current = this.currentBookingSubject.value;
    const progress = this.bookingProgressSubject.value;
    
    if (!current || !progress) return;
    
    // Actualizar validación de cada paso
    progress.steps[0].isValid = !!(current.checkInDate && current.checkOutDate);
    progress.steps[1].isValid = !!(current.guests && current.guests.total > 0);
    progress.steps[2].isValid = !!(current.guestInfo?.firstName && current.guestInfo?.email);
    
    // Calcular progreso
    const completedSteps = progress.steps.filter(s => s.isValid).length;
    progress.completionPercentage = (completedSteps / progress.totalSteps) * 100;
    progress.canProceed = progress.steps[progress.currentStep - 1]?.isValid || false;
    
    this.bookingProgressSubject.next(progress);
  }

  private addBooking(booking: Booking): void {
    const current = this.bookingsSubject.value;
    this.bookingsSubject.next([...current, booking]);
    this.saveBookingsToStorage([...current, booking]);
  }

  private loadBookingsFromStorage(): void {
    try {
      const saved = localStorage.getItem('hostal_norte_bookings');
      if (saved) {
        const bookings = JSON.parse(saved);
        this.bookingsSubject.next(bookings);
      }
    } catch (error) {
      console.warn('Error loading bookings from storage:', error);
    }
  }

  private saveBookingsToStorage(bookings: Booking[]): void {
    try {
      localStorage.setItem('hostal_norte_bookings', JSON.stringify(bookings));
    } catch (error) {
      console.warn('Error saving bookings to storage:', error);
    }
  }

  // Los demás métodos permanecen igual...
  validateCurrentBooking(): Observable<DateValidationResult> {
    const current = this.currentBookingSubject.value;
    if (!current || !current.checkInDate || !current.checkOutDate || !current.propertyId) {
      return of({
        isValid: false,
        errors: [{
          code: 'INCOMPLETE_BOOKING',
          message: 'Información de reserva incompleta',
          field: 'range'
        }],
        warnings: []
      });
    }
    
    return this.validateDateSelection(current.propertyId, current.checkInDate, current.checkOutDate);
  }

  sendWhatsAppMessage(booking: Booking): Observable<WhatsAppMessage> {
    const template = BOOKING_CONSTANTS.WHATSAPP_TEMPLATES['new-booking'];
    
    const messageText = this.populateWhatsAppTemplate(template, booking);
    const whatsappUrl = this.generateWhatsAppUrl(booking.hostWhatsapp, messageText);
    
    const message: WhatsAppMessage = {
      bookingId: booking.id,
      hostWhatsapp: booking.hostWhatsapp,
      messageText,
      messageType: 'new-booking',
      isSent: false,
      whatsappUrl
    };

    setTimeout(() => {
      message.isSent = true;
      message.sentAt = new Date().toISOString();
      this.updateBookingWhatsAppStatus(booking.id, true);
    }, 1000);
    
    return of(message).pipe(delay(100));
  }

  private updateBookingWhatsAppStatus(bookingId: string, sent: boolean): void {
    const current = this.bookingsSubject.value;
    const updated = current.map(booking => 
      booking.id === bookingId 
        ? { ...booking, whatsappMessageSent: sent, updatedAt: new Date().toISOString() }
        : booking
    );
    this.bookingsSubject.next(updated);
    this.saveBookingsToStorage(updated);
  }

  clearCurrentBooking(): void {
    this.currentBookingSubject.next(null);
    this.bookingProgressSubject.next(null);
  }

  getBookings(): Observable<Booking[]> {
    return this.bookings$;
  }

  getBookingById(id: string): Observable<Booking | undefined> {
    return this.bookings$.pipe(
      map(bookings => bookings.find(b => b.id === id))
    );
  }
}
